  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
}

::before,
::after {
  box-sizing: inherit;
}

li {
  padding: .25em;
  list-style-type: none;
  font-size: 1.5rem;
  text-wrap: balance;
}

a {
  text-decoration: none;
}

ul {
  border: 1px solid grey;
  display: inline-grid;
  grid-template-columns: auto auto;
  margin: 1em;
}

li:nth-child(odd) {
  text-align: right;
}

li:nth-child(even) a:before {
  content: "|";
  margin-right: .25em;

}</code></pre>
